CREATE TABLE retailer (retailer_id VARCHAR(12) PRIMARY KEY, retailer_name VARCHAR(120), category VARCHAR(80), pilot_zone VARCHAR(80), integration_type VARCHAR(40), pickup_model VARCHAR(50), partnership_status VARCHAR(50));
CREATE TABLE customer_order (order_id VARCHAR(16) PRIMARY KEY, order_datetime TIMESTAMP, zone VARCHAR(80), delivery_speed VARCHAR(20), order_status VARCHAR(30), retailer_count INT, merchandise_value_usd NUMERIC(10,2), customer_delivery_fee_usd NUMERIC(10,2), distance_surcharge_usd NUMERIC(10,2), retailer_commission_usd NUMERIC(10,2), retailer_transaction_fee_usd NUMERIC(10,2), partner_payout_usd NUMERIC(10,2), payment_processing_cost_usd NUMERIC(10,2), refund_amount_usd NUMERIC(10,2), prep_time_min INT, drive_time_min INT, retailer_wait_time_min INT, total_elapsed_min INT, membership_order BOOLEAN);
CREATE TABLE order_stop (order_id VARCHAR(16) REFERENCES customer_order(order_id), stop_sequence INT, retailer_id VARCHAR(12) REFERENCES retailer(retailer_id), retailer_name VARCHAR(120), stop_status VARCHAR(40), PRIMARY KEY(order_id,stop_sequence));
CREATE TABLE delivery_partner (partner_id VARCHAR(16) PRIMARY KEY, onboarding_status VARCHAR(30), identity_verified BOOLEAN, license_verified BOOLEAN, registration_verified BOOLEAN, insurance_verified BOOLEAN, background_check_status VARCHAR(30), driving_record_status VARCHAR(30));
CREATE TABLE partner_payout (payout_id VARCHAR(16) PRIMARY KEY, order_id VARCHAR(16) REFERENCES customer_order(order_id), partner_id VARCHAR(16), gross_earnings_usd NUMERIC(10,2), withdrawal_method VARCHAR(30), withdrawal_fee_usd NUMERIC(8,2), payout_status VARCHAR(30), initiated_at TIMESTAMP);
